glsl3.vert:
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
precision highp float;
in vec4 a_position;
in vec2 a_uv0;
out vec2 uv0;
void main()
{
    gl_Position = cc_matViewProj * a_position;
    uv0 = a_uv0;
}

glsl3.frag:
  precision highp float;
  in vec2 uv0;
  uniform sampler2D texture;
  uniform ARGS{
    vec4 u_mixColor;
    float u_edge;
  };
#if IS_Edge_Blur
  uniform ARGS1{
    float u_edgeBlur;
  };
#endif
#if IS_EdgeGlowing
  uniform ARGS2{
    float u_offset;
  };
#endif
#if USE_EDGE_COLOR
  uniform ARGS3{
    vec4 u_edgeColor;
  };
#endif
vec4 drawCircle() {
  float edge = u_edge;
  float dis = 0.0;
  float offset = 0.0;
  vec2 uv = uv0;
#if IS_EdgeGlowing
  offset =  u_offset;
  uv = vec2(0.5 + (uv0.x - 0.5) * ((offset*2.0) + 1.0), 0.5 + (uv0.y - 0.5) * ((offset*2.0) + 1.0));
#endif
        if ( uv.x < edge )
        {
            if ( uv.y < edge )
            {
                dis = distance( uv, vec2(edge, edge) );
            }
            if ( uv.y > (1.0 - edge) )
            {
                dis = distance( uv, vec2(edge, (1.0 - edge)) );
            }
        }
        else if ( uv.x > (1.0 - edge) )
        {
            if ( uv.y < edge )
            {
                dis = distance( uv, vec2((1.0 - edge), edge ) );
            }
            if ( uv.y > (1.0 - edge) )
            {
                dis = distance( uv, vec2((1.0 - edge), (1.0 - edge) ) );
            }
        }
        vec4 color = u_mixColor * texture2D(texture,uv);
        vec4 edge_color = color;
        float blur = 0.0;
      #if IS_Edge_Blur
          blur = u_edgeBlur;
      #endif
      #if USE_EDGE_COLOR
        #if USER_TEXTURE_COLOR
          edge_color = u_edgeColor  * texture2D(texture,uv);
        #else
          edge_color = u_edgeColor;
        #endif
      #endif
        if(dis > 0.001)
        {
            float gap = edge * blur;
            if(dis <= edge - gap)
            {
                color = color;
            }
            else if(dis <= edge)
            {
                float t = smoothstep(0.,gap,edge-dis);
                color = vec4(edge_color.rgb,t * edge_color.a);
            }else{
                #if IS_EdgeGlowing
                    color = vec4(edge_color.rgb, (offset - (dis - edge))/offset);
                  #else
                    color = vec4(edge_color.rgb,0.);
                #endif
            }
        }
        else
        {
          #if IS_EdgeGlowing
                float absX = abs(uv.x - 0.5);
                if(absX > 0.5)
                {
                    color = vec4( edge_color.rgb, (offset - (absX - 0.5))/offset);
                }
                else
                {
                    float absY = abs(uv.y - 0.5);
                    if (absY > 0.5){
                        color = vec4( edge_color.rgb, (offset - (absX - 0.5))/offset);
                    }
                    else{
                          color =  color;
                    }
                }
            #else
              color =  color;
          #endif
        }
    return  color;
}
    void main()
    {
      vec4 color = drawCircle();
      gl_FragColor = color;
    }

